function fatorial(n) {
  let resultado = 1n;
  for (let i = 2n; i <= n; i++) resultado *= i;
  return resultado;
}

console.log(fatorial(25n)); // 15511210043330985984000000n

console.log(10n === 10n); // true
console.log(10n === 10);  // false (tipos diferentes)
console.log(10n == 10);   // true (com coerção)

console.log(10n + BigInt(5)); // 15n

