const idadeUniversoAnos = 13_800_000_000n;
const segundosPorAno = 31_536_000n;

function anosParaSegundos(anos) {
  return anos * segundosPorAno;
}

console.log(anosParaSegundos(idadeUniversoAnos));
// 435196800000000000n

const vendasPorTrimestre = [[120, 150, 130], [200, 210], [90, 95, 100, 110]];

function resumoVendas(dados) {
  const todasAsVendas = dados.flat();
  const ultimaVenda = todasAsVendas.at(-1);
  return { todasAsVendas, ultimaVenda };
}

const { todasAsVendas, ultimaVenda } = resumoVendas(vendasPorTrimestre);
console.log(ultimaVenda); // 110

const vendasFormatadas = todasAsVendas.flatMap(valor =>
  valor < 100 ? [`Venda: ${valor}€`, "Aviso: venda baixa"] : [`Venda: ${valor}€`]
);

console.log(vendasFormatadas);
// ["Venda: 120€", "Venda: 150€", "Venda: 130€", "Venda: 200€", "Venda: 210€",
//  "Venda: 90€", "Aviso: venda baixa", "Venda: 95€", "Aviso: venda baixa",
//  "Venda: 100€", "Venda: 110€"]

const configBase = {
  tema: "escuro",
  modulosAtivos: new Set(["dashboard", "relatorios"]),
};

function criarConfiguracaoUtilizador(configBase, permissoesExtra) {
  const copia = structuredClone(configBase);

  for (const chave of Object.keys(permissoesExtra)) {
    if (Object.hasOwn(copia, chave)) {
      throw new Error(`Permissão já definida: ${chave}`);
    }
    copia[chave] = permissoesExtra[chave];
  }

  return copia;
}

const configUtilizador = criarConfiguracaoUtilizador(configBase, { exportarRelatorios: true });
configUtilizador.modulosAtivos.add("auditoria");

console.log(configBase.modulosAtivos);       // Set(2) {'dashboard', 'relatorios'}
console.log(configUtilizador.modulosAtivos); // Set(3) {'dashboard', 'relatorios', 'auditoria'}

async function obterResultado(a, b, precisaoAlta) {
  if (precisaoAlta) {
    const { calcular } = await import("./calculo-precisao-alta.js");
    return calcular(BigInt(a), BigInt(b));
  }

  const { calcular } = await import("./calculo-precisao-simples.js");
  return calcular(a, b);
}

